function validate(form) {
  const errors = {}
  if (!form.email) errors.email = '邮箱必填'
  else if (!/^[^@]+@[^@]+\.[^@]+$/.test(form.email)) errors.email = '邮箱格式错误'
  if (!form.password || form.password.length < 6) errors.password = '密码至少 6 位'
  return errors
}

function submit(form) {
  const errors = validate(form)
  if (Object.keys(errors).length) {
    console.warn('校验失败', errors)
    return
  }
  fetch('/api/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(form)
  })
}

let page = 1
let loading = false

window.addEventListener('scroll', async () => {
  const nearBottom =
    window.innerHeight + window.scrollY >= document.body.offsetHeight - 200
  if (nearBottom && !loading) {
    loading = true
    const res = await fetch(`/api/list?page=${page++}`)
    const data = await res.json()
    render(data)
    loading = false
  }
})

function toggleTheme() {
  const root = document.documentElement
  const isDark = root.getAttribute('data-theme') === 'dark'
  root.setAttribute('data-theme', isDark ? 'light' : 'dark')
  localStorage.setItem('theme', isDark ? 'light' : 'dark')
}

