/* 父容器使用 flex 实现子元素双向居中 */
.container {
  display: flex;
  align-items: center;     /* 交叉轴居中 */
  justify-content: center; /* 主轴居中 */
  height: 100vh;
}

.layout {
  display: grid;
  grid-template-columns: 240px 1fr; /* 侧边固定 240px，主区自适应 */
  gap: 16px;
}

.nav {
  position: sticky;
  top: 0;            /* 距视口顶部 0 时吸顶 */
  z-index: 100;
  background: #fff;
}

.box {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%); /* 反向偏移自身一半 */
}
